// Match triggers to segments
// Rules: missing-feature churn waits for that feature to ship; price churn waits for a plan change or an annual-discount window; seasonal churn waits for the season; poor-fit and closed-business are excluded.
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": { "type": "string" },
    "draft": { "type": "string", "description": "The message or document text this step produced, ready to send or review" },
    "subject": { "type": "string" },
    "confidence": { "type": "number" },
    "needs_human": { "type": "boolean" },
    "reasons": { "type": "array", "items": { "type": "string" } }
  },
  "required": ["summary", "confidence", "needs_human"]
}
